if 'current_subject' not in st.session_state:
    st.session_state.current_subject = None
if 'user_answers' not in st.session_state:
    st.session_state.user_answers = {}

def show_main_menu():
    st.title("📚 Образовательная Платформа Quardo")
    st.markdown("### Выберите предмет для проверки знаний:")
    col1, col2 = st.columns(2)
    with col1:
        if st.button("📜 История России", use_container_width=True, type="primary"):
            st.session_state.current_subject = "history"
            st.session_state.user_answers = {}
            st.rerun()
    with col2:
        if st.button("⚖️ Обществознание", use_container_width=True, type="primary"):
            st.session_state.current_subject = "society"
            st.session_state.user_answers = {}
            st.rerun()

def show_test():
    subject = st.session_state.current_subject
    questions_dict = st.session_state.quiz_db if subject == "history" else {k: v for k, v in st.session_state.quiz_db.items() if k not in [
        "1. Древняя Русь (IX-XI вв.)", "2. Политическая раздробленность (XII-XIII вв.)", "3. Монгольское нашествие и Александр Невский",
        "4. Возвышение Москвы (XIV-XV вв.)", "5. Иван Грозный и опричнина (XVI в.)", "6. Смутное время (конец XVI - начало XVII вв.)",
        "7. Первые Романовы и бунташный век (XVII в.)", "8. Петр I и Северная война (конец XVII - начало XVIII в.)",
        "9. Дворцовые перевороты и Екатерина II (XVIII в.)", "10. Александр I и Отечественная война 1812 года",
        "11. Николай I и общественная мысль (первая половина XIX в.)", "12. Александр II и Великие реформы (вторая половина XIX в.)"
    ]}
    subject_name = "📜 История России" if subject == "history" else "⚖️ Обществознание"
    
    st.title(subject_name)
    
    if st.button("← Назад к выбору предмета"):
        st.session_state.current_subject = None
        st.session_state.user_answers = {}
        st.rerun()
    
    st.markdown("---")
    
    topics = list(questions_dict.keys())
    selected_topic = st.selectbox("Выберите тему:", topics)
    
    topic_questions = questions_dict[selected_topic]
    
    if selected_topic not in st.session_state.user_answers:
        st.session_state.user_answers[selected_topic] = {}
    
    st.markdown(f"### {selected_topic}")
    st.write(f"Вопросов в теме: {len(topic_questions)}")
    st.markdown("---")
    
    for idx, q in enumerate(topic_questions):
        st.markdown(f"#### Вопрос {idx + 1}")
        st.write(q["q"])
        
        answer_key = f"ans_{subject}_{selected_topic}_{idx}"
        user_answer = st.radio("Выберите вариант ответа:", q["o"], key=answer_key, index=None)
        
        if user_answer is not None:
            if user_answer == q["c"]:
                st.success("✅ Правильно!")
                st.info(f"💡 **Пояснение:** {q['e']}")
            else:
                st.error(f"❌ Неверно. Правильный ответ: **{q['c']}**")
                st.info(f"💡 **Пояснение:** {q['e']}")
        
        st.markdown("---")

